    if (index != 0xFF)
        RfuReqDisconnectSlot(1 << index);

Rfu_DisconnectPlayerById.body:
if (playerIdx != 0)
    {
        s32 i;
        u8 toDisconnect = 0;

        for (i = 0; i < RFU_CHILD_MAX; i++)
        {
            if (gRfu.linkPlayerIdx[i] == playerIdx && (gRfu.parentSlots >> i) & 1)
                toDisconnect |= 1 << i;
        }
        if (toDisconnect)
            SendDisconnectCommand(toDisconnect, RFU_DISCONNECT_NORMAL);
